-- Allergen numbers on the print map to the app's keys: 1 gluten, 2 crustaceans, 3 eggs, 4 fish,
-- 5 peanuts, 6 soy, 7 milk, 8 tree nuts, 9 celery, 10 mustard, 11 sesame, 12 sulphites.
-- The additive letters A-F (caffeine, colouring ...) have no field in the database yet.
begin;

delete from public.menu_categories;   -- dishes go with them (on delete cascade)




commit;
